func (q *Queries) SetMessageRuleStatus(ctx context.Context, arg SetMessageRuleStatusParams) error {
	_, err := q.db.ExecContext(ctx, setMessageRuleStatus,
		arg.Status,
		arg.ApprovedBy,
		arg.ApprovedAt,
		arg.ApprovedVersion,
		arg.Now,
		arg.ID,
	)
	return err
}

const updateMessageRule = `-- name: UpdateMessageRule :exec
UPDATE ` + "`" + `message_rules` + "`" + ` SET title = ?, level = ?, kind = ?,
  priority = ?, placement = ?, content = ?,
  variants_enabled = ?, ab_split = ?, conditions = ?,
  exceptions = ?, cap_count = ?, cap_period = ?,
  cooldown_days = ?, hours_from = ?, hours_to = ?,
  starts_on = ?, ends_on = ?, audience_percent = ?,
  goal = ?, rule_key = ?, topics = ?, caps = ?,
  variants = ?, starts_at = ?, ends_at = ?,
  hour_windows = ?, goal_event = ?,
  status = ?, approved_by = ?, approved_at = ?,
  approved_version = ?, version = version + 1, updated_at = ?
WHERE id = ?
`

type UpdateMessageRuleParams struct {
	Title           string
	Level           string
	Kind            string
	Priority        uint16
	Placement       string
	Content         string
	VariantsEnabled bool
	AbSplit         uint8
	Conditions      string
	Exceptions      string
	CapCount        sql.NullInt16
	CapPeriod       sql.NullString
	CooldownDays    uint16
	HoursFrom       sql.NullInt16
	HoursTo         sql.NullInt16
	StartsOn        civildate.NullDate
	EndsOn          civildate.NullDate
	AudiencePercent uint8
	Goal            sql.NullString
	RuleKey         sql.NullString
	Topics          db.NullRawJSON
	Caps            db.NullRawJSON
	Variants        db.NullRawJSON
	StartsAt        sql.NullTime
	EndsAt          sql.NullTime
	HourWindows     db.NullRawJSON
	GoalEvent       sql.NullString
	Status          string
	ApprovedBy      sql.NullInt64
	ApprovedAt      sql.NullTime
	ApprovedVersion sql.NullInt32
	Now             sql.NullTime
	ID              uint64
}

// T-M10-02 (M-02, M-03): the version always grows; the caller decides the approval state — a text / condition /
// level / kind / topic / variant-content edit of a medical rule leaves it pending while approved_version keeps
// serving, an ops-only edit (priority, audience, schedule, hours, caps) keeps the approval.
func (q *Queries) UpdateMessageRule(ctx context.Context, arg UpdateMessageRuleParams) error {
	_, err := q.db.ExecContext(ctx, updateMessageRule,
		arg.Title,
		arg.Level,
		arg.Kind,
		arg.Priority,
		arg.Placement,
		arg.Content,
		arg.VariantsEnabled,
		arg.AbSplit,
		arg.Conditions,
		arg.Exceptions,
		arg.CapCount,
		arg.CapPeriod,
		arg.CooldownDays,
		arg.HoursFrom,
		arg.HoursTo,
		arg.StartsOn,
		arg.EndsOn,
		arg.AudiencePercent,
		arg.Goal,
		arg.RuleKey,
		arg.Topics,
		arg.Caps,
		arg.Variants,
		arg.StartsAt,
		arg.EndsAt,
		arg.HourWindows,
		arg.GoalEvent,
		arg.Status,
		arg.ApprovedBy,
		arg.ApprovedAt,
		arg.ApprovedVersion,
		arg.Now,
		arg.ID,
	)
	return err
}
